js.text:

function grid$dmkh0(f){
  this.constructor(f);
}
grid$dmkh0.prototype = new DirEvent();
grid$dmkh0.prototype.afterInit = function(){
  var p = this._dir;
  if (!$('#content .btn-action').length){
    var s = '<button class="btn-action btn-action-v1" id="btnViewTree"><div class="icon-btn-bottom ic-view-dept"></div></button>'
    $("#content").append(s);
    $("#btnViewTree").click(function () {
      var f = $("#tree_form_region");
      if(p.options._tblTreeData){
        $("#form_tree_region").show(150);
        $("#btnViewTree").hide(150);
      }
      else
        p.request('viewtree', 'GetTable', null, loadTree);
    });
    p.setSubtitle(['{rg_code}', $.msg.get('AllLabel'), '%s2', '']);
  }
}
function loadTree(p, d){
  var d = new DataTable(d);
  p.options._tblTreeData = d.obj.Rows;

  var treeID = "tree_region", treebox = $.fn.addTreeContainer(treeID, p.msg("TreeName"), null, function () {$("#btnViewTree").show(150);})
  $("#content").append(treebox);
  var fTree = $("#" + treeID).treeview({ tblData: d, expandAll: true
      , onSelectedItem: function(tr, v, v2){
        var m = p.options.memvars, vtext = (v == '')?$.msg.get('AllLabel'):v;
        m.val('rg_code', 'C', v2, 'FIND')
        p._setOptions({memvars:m, subtitle: ['{rg_code}', vtext, '%s2', '']});
      }, onCheckedItem: function(tr, v, flag){
        var m = p.options.memvars, v2 = tr.getCheckedItem(), vtext = (v2 == '') ? $.msg.get('AllLabel') : v2;
        m.val('rg_code', 'C', v2, 'FIND')
        p._setOptions({memvars:m, subtitle: ['{rg_code}', vtext, '%s2', '']});
      }
    });

  treebox.show(150);
  $("#btnViewTree").hide(150);
}

css.text:

.tree-form{
    width: 250px;
}
.ic-view-dept{
  background-position: 0px 0px;
}
		.table-bottom{
			left: 0px!important;
			height: calc(100% - 77px);
			top: 0px;
			position: relative;
			margin-top: 27px;
			clear: both;
			border-bottom: 1px solid #ddd;
		}
		#content .dir{
			position: relative !important;
			height: 100%;
		}

		@media only screen and (max-width: 767px) {
		  .table-bottom{
			margin-top: 42px;
			height: calc(100% - 92px);
		  }
		}
